// src/jsx/PrivateChat.jsx
import React, { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import {
  collection,
  addDoc,
  serverTimestamp,
  query,
  orderBy,
  onSnapshot,
  doc,
  setDoc,
  getDoc,
} from "firebase/firestore";

import Avatar from "./Avatar";
import useSearchUsers from "../hooks/useSearchUsers";
import { uploadMessageMedia } from "../js/supabaseUpload";

function makeRoomId(a, b) {
  return [a, b].sort().join("_");
}

// ----------------------------------------------
// Formatadores
// ----------------------------------------------
function formatTime(ts) {
  if (!ts) return "";
  const d = ts?.toDate ? ts.toDate() : new Date(ts);
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function formatDay(ts) {
  if (!ts) return "";
  const d = ts?.toDate ? ts.toDate() : new Date(ts);

  const today = new Date();
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);

  if (d.toDateString() === today.toDateString()) return "Hoje";
  if (d.toDateString() === yesterday.toDateString()) return "Ontem";

  return d.toLocaleDateString();
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {
  const roomId = makeRoomId(currentUser.uid, otherUser.id);
  const { allUsers } = useSearchUsers();

  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState("");
  const [uploading, setUploading] = useState(false);

  const listRef = useRef(null);

  // -------------------------------------------------
  // Inicializa sala e carrega mensagens
  // -------------------------------------------------
  useEffect(() => {
    let unsub;

    const setup = async () => {
      // cria room caso não exista
      const roomRef = doc(db, "rooms", roomId);
      const snap = await getDoc(roomRef);

      if (!snap.exists()) {
        await setDoc(roomRef, {
          id: roomId,
          members: [currentUser.uid, otherUser.id],
          createdAt: serverTimestamp(),
          lastMessage: "",
          lastUpdated: serverTimestamp(),
        });
      }

      // carrega mensagens
      const msgRef = collection(db, `rooms/${roomId}/messages`);
      const q = query(msgRef, orderBy("createdAt", "asc"));

      unsub = onSnapshot(q, (snap) => {
        const arr = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
        setMessages(arr);

        // scroll automático
        setTimeout(() => {
          if (listRef.current) {
            listRef.current.scrollTop = listRef.current.scrollHeight;
          }
        }, 50);
      });
    };

    setup();
    return () => {
      if (unsub) unsub();
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, [roomId]);

  // -------------------------------------------------
  // Seleção de arquivo
  // -------------------------------------------------
  function onSelectFile(e) {
    const f = e.target.files[0];
    if (!f) return;

    const maxMB = 40;
    if (f.size > maxMB * 1024 * 1024) {
      alert(`Arquivo muito grande. Limite: ${maxMB} MB.`);
      return;
    }

    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
  }

  // -------------------------------------------------
  // Enviar mensagem
  // -------------------------------------------------
  const send = async () => {
    if (!text.trim() && !file) return;

    setUploading(true);

    try {
      let url = "";
      let type = "text";

      if (file) {
        const up = await uploadMessageMedia(file, roomId);
        url = up.publicUrl;

        const mime = file.type.toLowerCase();
        if (mime.startsWith("image/")) type = "image";
        else if (mime.startsWith("video/")) type = "video";
        else type = "file";
      }

      await addDoc(collection(db, `rooms/${roomId}/messages`), {
        text: text.trim(),
        type,
        url,
        from: currentUser.uid,
        createdAt: serverTimestamp(),
      });

      await setDoc(
        doc(db, "rooms", roomId),
        {
          lastMessage:
            type === "text"
              ? text.trim()
              : type === "image"
              ? "[imagem]"
              : type === "video"
              ? "[vídeo]"
              : "[arquivo]",
          lastUpdated: serverTimestamp(),
        },
        { merge: true }
      );

      setText("");
      setFile(null);
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl("");
      }
    } catch (err) {
      console.error("Erro ao enviar:", err);
      alert("Erro ao enviar mensagem.");
    }

    setUploading(false);
  };

  const findUser = (id) => allUsers.find((u) => u.id === id);

  // ----------------------------------------------
  // Renderizar mensagens + separador de dias
  // ----------------------------------------------
  let lastDay = "";

  return (
    <>
      {/* HEADER */}
      <div className="chat-header">
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <button
            onClick={onClose}
            style={{
              background: "transparent",
              border: "none",
              color: "white",
              fontSize: 20,
              cursor: "pointer",
            }}
          >
            ←
          </button>
          <Avatar user={otherUser} size={44} />
          <div>
            <div style={{ fontWeight: 700 }}>{otherUser.nome || otherUser.email}</div>
            <div style={{ fontSize: 12, opacity: 0.9 }}>{otherUser.email}</div>
          </div>
        </div>
      </div>

      {/* LISTA DE MENSAGENS */}
      <div className="chat-box" ref={listRef}>
        {messages.map((m) => {
          const d = formatDay(m.createdAt);
          const showDay = d !== lastDay;
          lastDay = d;

          const isMe = m.from === currentUser.uid;
          const sender = findUser(m.from) || (m.from === otherUser.id ? otherUser : null);

          return (
            <React.Fragment key={m.id}>
              {/* separador de dia */}
              {showDay && (
                <div
                  style={{
                    textAlign: "center",
                    margin: "12px 0",
                    fontSize: 12,
                    color: "#555",
                  }}
                >
                  {d}
                </div>
              )}

              <div
                style={{
                  display: "flex",
                  marginBottom: 8,
                  alignItems: "flex-end",
                  justifyContent: isMe ? "flex-end" : "flex-start",
                }}
              >
                {!isMe && (
                  <div style={{ marginRight: 8 }}>
                    <Avatar user={sender} size={36} />
                  </div>
                )}

                <div style={{ maxWidth: "75%" }}>
                  <div className={`msg ${isMe ? "me" : "other"}`}>
                    {!isMe && (
                      <div style={{ fontSize: 12, fontWeight: 700, marginBottom: 6 }}>
                        {sender?.nome || sender?.email}
                      </div>
                    )}

                    {m.type === "image" && m.url ? (
                      <img
                        src={m.url}
                        alt="imagem"
                        style={{ maxWidth: "100%", borderRadius: 8 }}
                      />
                    ) : m.type === "video" && m.url ? (
                      <video
                        src={m.url}
                        controls
                        style={{ maxWidth: "100%", borderRadius: 8 }}
                      />
                    ) : (
                      <div style={{ whiteSpace: "pre-wrap" }}>{m.text}</div>
                    )}
                  </div>

                  <div
                    className="hora"
                    style={{ textAlign: isMe ? "right" : "left" }}
                  >
                    {formatTime(m.createdAt)}
                  </div>
                </div>

                {isMe && <div style={{ width: 36, marginLeft: 8 }} />}
              </div>
            </React.Fragment>
          );
        })}
      </div>

      {/* INPUT */}
      <div className="chat-input" style={{ flexDirection: "column", gap: 8 }}>
        {/* preview */}
        {previewUrl && (
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            {file?.type.startsWith("image/") && (
              <img
                src={previewUrl}
                style={{ width: 120, height: 80, borderRadius: 8, objectFit: "cover" }}
              />
            )}

            {file?.type.startsWith("video/") && (
              <video
                src={previewUrl}
                controls
                style={{ width: 160, height: 100, borderRadius: 8 }}
              />
            )}

            <div>
              <div style={{ fontWeight: 700, fontSize: 13 }}>{file.name}</div>
              <div style={{ fontSize: 12, color: "#666" }}>
                {(file.size / 1024 / 1024).toFixed(2)} MB
              </div>
            </div>

            <button
              onClick={() => {
                setFile(null);
                URL.revokeObjectURL(previewUrl);
                setPreviewUrl("");
              }}
              style={{ marginLeft: "auto" }}
            >
              Remover
            </button>
          </div>
        )}

        <div style={{ display: "flex", gap: 10 }}>
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Mensagem..."
            style={{
              flex: 1,
              padding: 12,
              borderRadius: 25,
              border: "1px solid #ccc",
            }}
          />

          <label
            style={{
              padding: "10px 14px",
              background: "#fff",
              border: "1px solid #ccc",
              borderRadius: 25,
              cursor: "pointer",
            }}
          >
            📎
            <input
              type="file"
              accept="image/*,video/*"
              style={{ display: "none" }}
              onChange={onSelectFile}
            />
          </label>

          <button
            onClick={send}
            disabled={uploading}
            style={{
              padding: "10px 20px",
              borderRadius: 25,
              border: "none",
              background: "#075E54",
              color: "white",
              cursor: "pointer",
            }}
          >
            {uploading ? "Enviando..." : "Enviar"}
          </button>
        </div>
      </div>
    </>
  );
}
